class LamportNode:
    def __init__(self, node_id):
        self.id = node_id
        self.clock = 0
    def send(self):
        self.clock += 1
        return self.clock
    def receive(self, received_time):
        self.clock = max(self.clock, received_time) + 1
        return self.clock

class FIFOReceiver:
    def __init__(self):
        self.next_seq = 0
        self.buffer = {}
    def receive(self, seq, data):
        if seq == self.next_seq:
            print(f'Delivering: {data}')
            self.next_seq += 1
            while self.next_seq in self.buffer:
                print(f'Delivering buffered: {self.buffer.pop(self.next_seq)}')
                self.next_seq += 1
        elif seq > self.next_seq:
            self.buffer[seq] = data

def validate_causal_delivery(received_log, dependency_graph):
    for msg, deps in dependency_graph.items():
        for d in deps:
            if received_log.index(d) > received_log.index(msg):
                return False
    return True

