# AWS Lambda style Serverless function in Python 3.12+
import json

def lambda_handler(event, context):
    """
    Event-driven serverless function handler.
    Triggered by an HTTP request via API Gateway or direct invocation.
    """
    print(f"Received event: {json.dumps(event)}")

    # Extracting query parameters safely
    name = event.get('queryStringParameters', {}).get('name', 'Guest')

    response_payload = {
        "message": f"Hello, {name}! Welcome to Serverless Computing.",
        "status": "success"
    }

    return {
        "statusCode": 200,
        "headers": {"Content-Type": "application/json"},
        "body": json.dumps(response_payload)
    }

# Simulated test invocation
if __name__ == '__main__':
    mock_event = {"queryStringParameters": {"name": "Gurugram University Student"}}
    print(lambda_handler(mock_event, None))

