# Python serverless function to process an incoming JSON payload and return total price
def lambda_handler(event, context):
    body = event.get('body', '{}')
    if isinstance(body, str):
        import json
        body = json.loads(body)
    price = body.get('price', 0)
    quantity = body.get('quantity', 1)
    total = price * quantity
    return {"statusCode": 200, "total_cost": total}
